config.prelude:
static int lock_depth;
static int lock_enter_count;
static int lock_exit_count;
static int lock_balance_errors;

void test_reset_lock_stats(void) {
    lock_depth = 0;
    lock_enter_count = 0;
    lock_exit_count = 0;
    lock_balance_errors = 0;
}

void enter_critical(void) {
    lock_enter_count++;
    if (lock_depth != 0) {
        lock_balance_errors++;
    }
    lock_depth++;
}

void exit_critical(void) {
    lock_exit_count++;
    if (lock_depth != 1) {
        lock_balance_errors++;
    }
    if (lock_depth > 0) {
        lock_depth--;
    }
}

int test_lock_enters(void) { return lock_enter_count; }
int test_lock_exits(void) { return lock_exit_count; }
int test_lock_depth(void) { return lock_depth; }
int test_lock_errors(void) { return lock_balance_errors; }
